import base64, hashlib, io, json, os, subprocess, sys, tarfile
from pathlib import Path
root = Path("/tmp/code"); root.mkdir(parents=True, exist_ok=True)
with tarfile.open(fileobj=io.BytesIO(base64.b64decode("")), mode="r:gz") as tar:
    tar.extractall(root)
manifest = {"shared/__init__.py": "a5d8360a9c1a06dc42b0b1c336e0cfaa7e7edd4605ee67daf1049bc0798edb36", "shared/data_split.py": "f534c584da409642b0462d48c5c88f1658e6ce9f310b22996ca4461369ce780e", "shared/utils.py": "97c2ffb5c4b0b870775769988295533ddf5142499080f41df4fe31b2b6e17a44", "experiments/exp_033_inference/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "experiments/exp_033_inference/src/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "experiments/exp_033_inference/src/sweep.py": "9923412adb27609fe2d70a51e7baa80559addf99ca85999c65cd8fc062b6c01b", "experiments/exp_033_inference/src/cached_tta.py": "f412a55a51afdc81347690bd47bae15d60766b6fc18e4b11490e194f3263b0c6", "experiments/exp_139_mask2former/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "experiments/exp_139_mask2former/src/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "experiments/exp_139_mask2former/src/data.py": "9b3054ddcc819f99c24780c5ff06d502d1133514a8b33547ae08de3a40e6f6e9", "experiments/exp_139_mask2former/src/model.py": "f3c20a18972e442c5a988b3955c9e7a95f50a53ceac1d6b873e638ae533f0c79", "experiments/exp_139_mask2former/src/evaluate.py": "df143da11fe4b3546bd86e764612d6f592c4252fd38b642c73dc098424bf1817", "experiments/exp_139_mask2former/src/fast_ops.py": "6c92c64061e6139074e29a4789f7f65399533277bd8c98c8cc0a567797beaaa4", "experiments/exp_139_mask2former/src/submit.py": "5e9ad3bbbc7c21bfdaf380f3f752e6c7ac2927135a85b08b7018b75ff89d820d", "experiments/exp_141_soup_and_tta/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "experiments/exp_141_soup_and_tta/src/__init__.py": "e3b0c44298fc1c149afbf4c8996fb92427ae41e4649b934ca495991b7852b855", "experiments/exp_141_soup_and_tta/src/soup_tta.py": "d3703f0fb2faf8d0320982598c1db95a4ed1c665d18269fdb786dda0b9b5a5af", "experiments/exp_141_soup_and_tta/src/emit_fusion.py": "8467ef00d09c2351c2ef3ce3b1675ba818133d030467f4351449f85bfc0a2135"}
for name, digest in manifest.items():
    assert hashlib.sha256((root / name).read_bytes()).hexdigest() == digest, name
print("CODE_VERIFIED", len(manifest), flush=True)
def run(command):
    print("RUN", " ".join(command), flush=True)
    subprocess.run(command, check=True)
run([sys.executable, "-m", "pip", "uninstall", "-y", "-q", "torchvision", "torchaudio"])
run([sys.executable, "-m", "pip", "install", "-q", "torch==2.8.0", "--index-url", "https://download.pytorch.org/whl/cu128"])
run([sys.executable, "-m", "pip", "install", "-q", "transformers==4.57.6", "kernels", "pycocotools", "scipy"])
source = Path("/kaggle/input")
annotations = next(source.rglob("MAGFiLO_1.0_Annotations_kaggle2026_train.json"))
assert hashlib.sha256(annotations.read_bytes()).hexdigest() == "5da9e92b5a1a1947fd5d57adb6688269625c48ec1ef884daf2a01618c9ed54a1"
test_images = next(p for p in source.rglob("test_images") if p.is_dir())
weights = [p.parent for p in source.rglob("manifest.json") if "sol-exp139-mask2former-weights" in str(p)]
assert len(weights) == 1, [str(p) for p in weights]
checkpoint = weights[0] / "model_e040.pt"
recorded = json.loads((weights[0] / "manifest.json").read_text())
assert hashlib.sha256(checkpoint.read_bytes()).hexdigest() == recorded[checkpoint.name]["sha256"]
print("CHECKPOINT", checkpoint.name, flush=True)
env = dict(os.environ, PYTHONPATH=str(root), PYTHONUNBUFFERED="1", HF_HUB_ENABLE_HF_TRANSFER="0")
result = subprocess.run([sys.executable, "-u", "-m", "experiments.exp_141_soup_and_tta.src.emit_fusion",
                         "--checkpoint", str(checkpoint), "--test-images", str(test_images),
                         "--output", "/kaggle/working", "--log", "/kaggle/working/events.log"],
                        cwd=root, env=env)
print("EMIT_EXIT", result.returncode, flush=True)
for csv in sorted(Path("/kaggle/working").glob("submission_*.csv")):
    rows = sum(1 for _ in csv.open()) - 1
    print("CSV", json.dumps(dict(name=csv.name, rows=rows, bytes=csv.stat().st_size)), flush=True)
print("KERNEL_COMPLETE", flush=True)
